/**
 ******************************************************************************
 * @file    msc_store.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   USB-MSC <-> SD backing-store manager — PD5b refactor.
 *
 * Owner: Brendon Bone. Logic ported from my USER CODE blocks in
 * usbd_storage_if.c, with the SD access injected and the post-I/O card-state
 * wait bounded (the demo code spun forever if the card wedged).
 * Rules and who calls what on the board: see msc_store.h (no task of its
 * own; the block calls run inside the USB interrupt).
 *
 * MSC_Poll, step by step:
 *   1. ask the card's state: READY -> done; BUSY -> leave it alone
 *   2. otherwise, at most once per MSC_INIT_RETRY_MS (500 ms): a full
 *      re-init (card_init)
 *   3. then try the faster 4-bit bus; if that fails, stay on the 1-bit bus
 * A block read or write: 1. the transfer (read_blocks / write_blocks);
 * 2. poll the card back to READY, at most MSC_WAIT_MAX_POLLS times.
 * Generative AI was used to assist in the refactoring process.
 ******************************************************************************
 */
#include "msc_store.h"

#include <stddef.h>

/**
 * @brief Validate that an ops table is complete.
 */
static MSC_Status msc_ops_ok(const MSC_SdOps *ops)
{
    if (ops == NULL ||
        ops->get_state == NULL || ops->card_init == NULL ||
        ops->config_wide_bus == NULL || ops->read_blocks == NULL ||
        ops->write_blocks == NULL || ops->get_capacity == NULL) {
        return MSC_BAD_PARAM;
    }
    return MSC_OK;
}

/**
 * @brief Poll the card back to idle after a block transfer.
 *
 * Bounded replacement for the demo's `while (state != TRANSFER) {}` spin:
 * a wedged card now surfaces as MSC_TIMEOUT instead of hanging the USB ISR.
 */
static MSC_Status msc_wait_idle(const MSC_Store *store)
{
    uint32_t polls;

    for (polls = 0U; polls < MSC_WAIT_MAX_POLLS; polls++) {
        if (store->ops->get_state(store->ops->ctx) == (int)MSC_CARD_READY) {
            return MSC_OK;
        }
    }

    return MSC_TIMEOUT;
}

/**
 * @brief Initialise the store with injected SD operations and fallbacks.
 */
MSC_Status MSC_Init(MSC_Store *store, const MSC_SdOps *ops,
                    uint32_t fallback_blk_nbr, uint16_t fallback_blk_siz)
{
    if (store == NULL || msc_ops_ok(ops) != MSC_OK) {
        return MSC_BAD_PARAM;
    }

    store->ops              = ops;
    store->last_init_try_ms = 0U;
    store->init_attempted   = 0U;
    store->wide_bus_ok      = 0U;
    store->fallback_blk_nbr = fallback_blk_nbr;
    store->fallback_blk_siz = fallback_blk_siz;

    return MSC_OK;
}

/**
 * @brief Thread-context bring-up poll (see header for the state rules).
 */
MSC_Status MSC_Poll(MSC_Store *store, uint32_t now_ms)
{
    int state;

    if (store == NULL || store->ops == NULL) {
        return MSC_BAD_PARAM;
    }

    state = store->ops->get_state(store->ops->ctx);

    if (state == (int)MSC_CARD_READY) {
        return MSC_OK;              /* already up and idle */
    }
    if (state == (int)MSC_CARD_BUSY) {
        return MSC_BUSY;            /* mid-transfer (the demo's case: the recorder writing) — don't disturb */
    }

    /* Not initialised / no card / error: attempt a rate-limited bring-up.
     * (init_attempted replaces the demo's "last try == 0" sentinel so an
     * attempt at tick 0 is handled correctly.) */
    if (store->init_attempted == 1U &&
        (uint32_t)(now_ms - store->last_init_try_ms) < MSC_INIT_RETRY_MS) {
        return MSC_RATE_LIMITED;
    }
    store->last_init_try_ms = now_ms;
    store->init_attempted   = 1U;

    if (store->ops->card_init(store->ops->ctx) != 0) {
        return MSC_ERROR;
    }

    /* Bump to 4-bit for host file-copy speed. Best-effort: if the wide-bus
     * switch fails we keep the reliable 1-bit mode. */
    store->wide_bus_ok =
        (store->ops->config_wide_bus(store->ops->ctx) == 0) ? 1U : 0U;

    return MSC_OK;
}

/**
 * @brief 1 when the card is initialised and idle.
 */
uint8_t MSC_IsReady(const MSC_Store *store)
{
    if (store == NULL || store->ops == NULL) {
        return 0U;
    }
    return (store->ops->get_state(store->ops->ctx) == (int)MSC_CARD_READY)
               ? 1U : 0U;
}

/**
 * @brief 1 if the last bring-up achieved 4-bit mode.
 */
uint8_t MSC_WideBusActive(const MSC_Store *store)
{
    return (store != NULL && store->wide_bus_ok == 1U) ? 1U : 0U;
}

/**
 * @brief Read whole blocks for the host, then wait for the card to go idle.
 */
MSC_Status MSC_ReadBlocks(const MSC_Store *store, uint8_t *buf,
                          uint32_t blk_addr, uint16_t blk_len)
{
    if (store == NULL || store->ops == NULL || buf == NULL || blk_len == 0U) {
        return MSC_BAD_PARAM;
    }

    if (store->ops->read_blocks(store->ops->ctx, buf, blk_addr, blk_len) != 0) {
        return MSC_ERROR;
    }

    return msc_wait_idle(store);
}

/**
 * @brief Write whole blocks from the host, then wait for the card to go idle.
 */
MSC_Status MSC_WriteBlocks(const MSC_Store *store, const uint8_t *buf,
                           uint32_t blk_addr, uint16_t blk_len)
{
    if (store == NULL || store->ops == NULL || buf == NULL || blk_len == 0U) {
        return MSC_BAD_PARAM;
    }

    if (store->ops->write_blocks(store->ops->ctx, buf, blk_addr, blk_len) != 0) {
        return MSC_ERROR;
    }

    return msc_wait_idle(store);
}

/**
 * @brief Report the medium capacity: true geometry when ready, else fallback.
 */
MSC_Status MSC_GetCapacity(const MSC_Store *store,
                           uint32_t *block_num, uint16_t *block_size)
{
    if (store == NULL || store->ops == NULL ||
        block_num == NULL || block_size == NULL) {
        return MSC_BAD_PARAM;
    }

    if (store->ops->get_state(store->ops->ctx) == (int)MSC_CARD_READY &&
        store->ops->get_capacity(store->ops->ctx, block_num, block_size) == 0) {
        return MSC_OK;
    }

    /* Card not ready yet — report the fallback geometry so enumeration
     * doesn't bomb; IsReady keeps saying "not ready" until the card is up,
     * and the host then re-reads the capacity. */
    *block_num  = store->fallback_blk_nbr;
    *block_size = store->fallback_blk_siz;
    return MSC_FALLBACK;
}
